import os, json, re

d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
session_path = os.path.join(d, '..', '..', 'sessions', os.path.basename(d) + '.jsonl')

G = {}

with open(session_path, 'rb') as f:
    for line in f:
        obj = json.loads(line)
        if obj.get('role') == 'toolResult':
            text = obj.get('content', [{}])[0].get('text', '')
            if 'Demo pair' in text:
                print('Found Demo pair in toolResult!')
                match = re.search(r'Message format: Demo pair (\d+) INPUT \((\d+)x(\d+)\):\s*\n([0-9 ]+)\n', text, re.DOTALL)
                if match:
                    pair_num, h, w = match.group(1), match.group(2), match.group(3)
                    print(f'  Demo pair {pair_num}: {h}x{w}')
                    grid_text = match.group(4)
                    rows = grid_text.split('\n')
                    grid = [[int(x) for x in row.split()] for row in rows]
                    G[f'demo_{pair_num}'] = grid

print(f'Total grids found: {len(G)}')
if G:
    for k, v in G.items():
        print(f'  {k}: {len(v)}x{len(v[0]) if v else 0}')

